class SemanticConcept(BaseModel):
    """
    EXPERIMENTAL A semantic concept. Concepts can be entities, properties, shared properties, metrics, or groups (selected via `kind`).
    Field availability depends on `kind`: property fields (`data_type`, `required`, `unique`, `business_name`, `examples`, `enum`, `pattern`) only apply to `property` and `shared_property`; metric fields (`unit`, `better_when`, `formula`) only apply to `metric`; `properties` only applies to `entity`.

    """

    id: str | None = Field(None, examples=["customer"])
    """
    An organizational unique technical identifier for this concept within the namespace. Must match the path parameter when both are provided. Can contain "/".
    """
    name: str = Field(..., examples=["Customer"])
    """
    A human-readable name for the concept.
    """
    kind: SemanticConceptKind | None = "entity"
    description: str | None = None
    """
    A description of the concept.
    """
    iri: str | None = None
    """
    An optional IRI identifying the concept (typically used to link to an external ontology).
    """
    status: str | None = Field(None, examples=["active"])
    """
    A free-form lifecycle status for this concept (e.g., draft, active, deprecated).
    """
    group: str | None = None
    """
    The external id of a `group` concept that this concept belongs to.
    """
    team: str | None = Field(None, examples=["checkout"])
    """
    The owning team's external id. The caller must have edit permission on the team to set this.
    """
    domain: str | None = None
    """
    An optional domain identifier.
    """
    classification: str | None = None
    """
    An optional data classification (e.g., internal, confidential, pii).
    """
    tags: list[str] | None = Field(None, examples=[["core"]])
    ai_context: dict[str, Any] | None = None
    """
    A free-form map of context hints used by AI features.
    """
    custom_properties: dict[str, Any] | None = None
    """
    OSI open escape hatch (PR #146). A free-form map for data not covered by the core spec — IRIs, owl:equivalentClass, provenance — and language-tagged literals via the `name@lang` key convention (e.g. `name@de`, `description@fr`). Accepts the prior `custom_fields` name.
    """
    data_type: str | None = Field(None, examples=["string"])
    """
    Property-only. The data type of the property (e.g., string, integer, boolean).
    """
    required: bool | None = None
    """
    Property-only. Whether the property is required.
    """
    unique: bool | None = None
    """
    Property-only. Whether the property is unique.
    """
    business_name: str | None = None
    """
    Property-only. A business-friendly name for the property.
    """
    examples: list[str] | None = None
    """
    Property-only. Example values for the property.
    """
    enum: list[str] | None = None
    """
    Property-only. The set of allowed values for the property.
    """
    pattern: str | None = None
    """
    Property-only. A regular expression that values of the property must match.
    """
    unit: str | None = None
    """
    Metric-only. The unit of the metric (e.g., USD, count, percent).
    """
    better_when: str | None = None
    """
    Metric-only. A hint about whether higher or lower values are better (e.g., higher, lower).
    """
    formula: str | None = None
    """
    Metric-only. The formula used to compute the metric.
    """
    properties: list[SemanticConcept | SemanticConceptPropertyOption2] | None = None
    """
    Entity-only. The list of properties for an entity. Each entry is either an inline property definition (a SemanticConcept with `kind: property`) or a shared-property reference of the form `{ "ref": "<externalId>" }`. Sending `null` preserves existing properties; sending an empty list removes them all.

    """


