class SemanticBranch(BaseModel):
    """
    EXPERIMENTAL A branch of a semantic namespace: a hidden namespace holding a copy of it, where
    changes are authored before they are merged back.

    """

    name: str | None = Field(None, examples=["add-subscription-billing"])
    """
    The branch name, as it was cut.
    """
    namespace: str | None = Field(None, examples=["main"])
    """
    The namespace the branch was cut from.
    """
    branch_namespace: str | None = Field(None, examples=["branch-main-add-subscription-billing"])
    """
    The hidden namespace slug the branch is stored under. Informational — the namespace endpoints refuse it; author through `…/branches/{branch}/ontology.yaml`.
    """
    behind_target: bool | None = None
    """
    Whether the namespace has changed since the branch was last updated from it. When true, a rebase has something to take on.
    """
    conflicted: bool | None = None
    """
    Whether the last replay onto the namespace disagreed. A conflicted branch cannot be merged until its author resolves it.
    """
    conflicts: list[SemanticBranchConflict] | None = None
    """
    Where that replay disagreed, if anywhere. Empty while the branch replays cleanly.
    """
    merge_request: SemanticBranchMergeRequest | None = None
    """
    The pull/merge request opened from the branch, while one is open. Its live fields (status, mergeability, comment count) are filled when reading a single branch and left out in the list.
    """


class SemanticBranchChange(BaseModel):
    """
    EXPERIMENTAL One change of a branch — always a concept.

    Inline properties and relationships are reviewed as part of the concept they hang off and appear
    under `properties` and `relationships` rather than as entries of their own.

    """

    external_id: str | None = Field(None, examples=["customer"])
    element_type: SemanticBranchChangeElementType | None = None
    name: str | None = Field(None, examples=["Customer"])
    op: SemanticBranchChangeOp | None = None
    impact: SemanticBranchChangeImpact | None = None
    warnings: list[str] | None = None
    """
    `renamedAndRedefined` means the edit changed both the name and what it says, which is what a different concept reusing an id looks like.
    """
    fields: list[SemanticBranchFieldChange] | None = None
    properties: list[SemanticBranchNestedChange] | None = None
    """
    Changes to inline properties this concept holds.
    """
    relationships: list[SemanticBranchNestedChange] | None = None
    """
    Changes to relationships hanging off this concept.
    """


